LRESULT CALLBACK WindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
	static std::string password;
	static bool hasEnteredPassword = false;

	switch (uMsg)
	{
	case WM_CREATE:
	{
		HWND hEdit = CreateWindowEx(0, TEXT("edit"), TEXT(""), WS_CHILD | WS_VISIBLE | WS_BORDER | ES_PASSWORD, 10, 10, 200, 25, hwnd, nullptr, nullptr, nullptr);
		HWND hButton = CreateWindowEx(0, TEXT("button"), TEXT("Ввести"), WS_CHILD | WS_VISIBLE, 10, 40, 100, 25, hwnd, reinterpret_cast<HMENU>(1), nullptr, nullptr);
		break;
	}
	case WM_COMMAND:
	{
		if (LOWORD(wParam) == 1)
		{
			HWND hEdit = GetDlgItem(hwnd, 0);
			int length = GetWindowTextLength(hEdit);
			password.assign(length, ‘\0’);
			GetWindowTextA(hEdit, &password[0], length + 1);

			MessageBox(hwnd, TEXT("Пароль сохранен."), TEXT("Вход запрещен"), MB_OK | MB_ICONINFORMATION);

			hasEnteredPassword = true;
			ShowWindow(hwnd, SW_HIDE);
			break;
		}
		break;
	}
	case WM_CLOSE:
	{
		if (hasEnteredPassword)
		{
			DestroyWindow(hwnd);
		}
		else
		{
			MessageBox(hwnd, TEXT("Введите пароль."), TEXT("Ошибка"), MB_OK | MB_ICONERROR);
		}
		break;
	}
	case WM_DESTROY:
	{
		PostQuitMessage(0);
		break;
	}
	default:
		return DefWindowProc(hwnd, uMsg, wParam, lParam);
	}
	return 0;
}

