func main() {
	// Podanie ścieżki pliku DMG wejściowego
	dmgPath := "plik.dmg"

	// Podanie ścieżki pliku ZIP wyjściowego
	zipPath := "plik.zip"

	// Otwieranie pliku DMG
	dmgFile, err := os.Open(dmgPath)
	if err != nil {
		log.Fatal(err)
	}
	defer dmgFile.Close()

	// Tworzenie pliku ZIP wyjściowego
	zipFile, err := os.Create(zipPath)
	if err != nil {
		log.Fatal(err)
	}
	defer zipFile.Close()

	// Inicjalizowanie bufora do kopiowania danych
	buffer := make([]byte, 1024)

	// Tworzenie archiwum ZIP
	zipWriter := zip.NewWriter(zipFile)

	// Dodawanie pliku DMG do archiwum ZIP
	dmgInfo, err := dmgFile.Stat()
	if err != nil {
		log.Fatal(err)
	}
	dmgHeader, err := zip.FileInfoHeader(dmgInfo)
	if err != nil {
		log.Fatal(err)
	}
	dmgHeader.Name = dmgPath
	dmgWriter, err := zipWriter.CreateHeader(dmgHeader)
	if err != nil {
		log.Fatal(err)
	}
	_, err = io.Copy(dmgWriter, dmgFile)
	if err != nil {
		log.Fatal(err)
	}

	// Zamykanie archiwum ZIP
	err = zipWriter.Close()
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("Konwersja DMG do ZIP zakończona pomyślnie.")
}
