#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 32
#define OLED_RESET     4
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

const int analogPin = A0;
const int lampPin = 3;
const int numReadings = 100;
const unsigned long updateInterval = 5000;

unsigned long lastUpdateTime = 0;
float signalReadings[numReadings];
int readingIndex = 0;
float Vmin = 1.0;
float Vmax = 5.0;

void setup() {
  pinMode(analogPin, INPUT);
  pinMode(lampPin, OUTPUT);

  Serial.begin(9600);

  if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println(F("SSD1306 allocation failed"));
    for(;;);
  }
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
}

void loop() {
  float voltageReading = analogRead(analogPin) * (5.0 / 1023.0);
  signalReadings[readingIndex] = voltageReading;
  readingIndex = (readingIndex + 1) % numReadings;

  float threshold = (Vmax + Vmin) / 2;
  if (voltageReading >= threshold) {
    digitalWrite(lampPin, HIGH);
  } else {
    digitalWrite(lampPin, LOW);
  }

  if (millis() - lastUpdateTime >= updateInterval) {
    lastUpdateTime = millis();
    updateDisplay();
  }
}

void updateDisplay() {
  display.clearDisplay();
  display.setCursor(0, 0);

  float avgFrequency = getAverageFrequency();
  float avgVoltage = (Vmax + Vmin) / 2;

  display.print("Voltage: ");
  display.print(avgVoltage, 2);
  display.print("V");
  display.setCursor(0, 10);
  display.print("Frequency: ");
  display.print(avgFrequency, 2);
  display.print("Hz");
  display.display();
}

float getAverageFrequency() {
  // Implement a frequency detection algorithm here, such as zero-crossing or autocorrelation
  // This example uses a simple zero-crossing algorithm

  int zeroCrossings = 0;
  bool lastState = false;
  float threshold = (Vmax + Vmin) / 2;

  for (int i = 0; i < numReadings; i++) {
    bool currentState = signalReadings[i] >= threshold;
    if (currentState != lastState) {
      zeroCrossings++;
      lastState = currentState;
    }
  }

  float frequency = (zeroCrossings / 2.0) * (1000.0 / updateInterval);
  return frequency;
}
