#include <iostream>

using namespace ComplexLib;

int main() {
    try {
        Complex<double> c1(2.5, -1.7);
        Complex<double> c2(0, 0);

        // Взаимодействие с классом через геттеры и сеттеры
        std::cout << "c1: " << c1.getreal() << (c1.getimag() < 0 ? " - " : " + ") << std::abs(c1.getimag()) << "i" << std::endl;
        c1.setreal(3.5);
        c1.setimag(-2.3);
        std::cout << "Modified c1: " << c1.getreal() << (c1.getimag() < 0 ? " - " : " + ") << std::abs(c1.getimag()) << "i" << std::endl;

        // Операции над комплексными числами
        Complex<double> sum = c1 + c2;
        Complex<double> difference = c1 - c2;
        Complex<double> product = c1 * c2;
        Complex<double> quotient = c1 / c2;

        std::cout << "Sum: " << sum.getreal() << (sum.getimag() < 0 ? " - " : " + ") << std::abs(sum.getimag()) << "i" << std::endl;
        std::cout << "Difference: " << difference.getreal() << (difference.getimag() < 0 ? " - " : " + ") << std::abs(difference.getimag()) << "i" << std::endl;
        std::cout << "Product: " << product.getreal() << (product.getimag() < 0 ? " - " : " + ") << std::abs(product.getimag()) << "i" << std::endl;
        std::cout << "Quotient: " << quotient.getreal() << (quotient.getimag() < 0 ? " - " : " + ") << std::abs(quotient.getimag()) << "i" << std::endl;

        double abs = c1.abs();
        std::cout << "abs of c1: " << abs << std::endl;

        Complex<double> power = c1.pow(3);
        std::cout << "c1 to the power of 3: " << power.getreal() << (power.getimag() < 0 ? " - " : " + ") << std::abs(power.getimag()) << "i" << std::endl;

        Complex<double> square = c1.sqrt();
        std::cout << "Square root of c1: " << square.getreal() << (square.getimag() < 0 ? " - " : " + ") << std::abs(square.getimag()) << "i" << std::endl;
    }
    catch (const char* message) {
        std::cerr << "Error: " << message << std::endl;
    }

    return 0;
}

